(function (global) {
  'use strict';
  var pack = {"manifest":{"id":"drilling-fluid","sceneId":"d5","title":"钻井液性能智能调控","status":"ready","version":"1.0.0","updated":"2026-10-23","methods":["ts","opt"],"tabs":{"background":{"label":"专业背景","lede":"钻井液流变性能影响流动阻力和岩屑输送，处理剂作用又随温度和固相状态改变。小试记录可用于建立轻量代理模型，比较性能窗口内的加剂方案，减少只凭单一性能调节的盲目性。","judge":[{"label":"数据来源","value":"教学合成","desc":"固定种子，可导出核查"},{"label":"方法类型","value":"双输出回归与配方搜索","desc":"纯前端轻量计算"},{"label":"输出用途","value":"教学比较","desc":"不连接设备与现场系统"},{"label":"评价边界","value":"合成任务","desc":"不声称真实工程收益"}],"sections":[{"no":1,"en":"BUSINESS","title":"钻井液流变性能与处理剂","html":"<p>本例使用 Bingham 近似：剪切应力 τ=YP+PV×剪切速率。PV 为塑性黏度，表示屈服后的斜率；YP 为动切力，对应截距。PV 用 mPa·s、YP 用 Pa。实际钻井液可能需要幂律或 Herschel–Bulkley 模型，本例不将 Bingham 近似作为通用规律。</p><figure class=\"figure\"><div style=\"overflow-x:auto\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 118\" role=\"img\" aria-label=\"钻井液流变性能与处理剂\" style=\"width:100%;min-width:560px;max-width:640px;display:block;margin:auto\"><rect x=\"18\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"105\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">循环状态与小试</text><text x=\"105\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">温度 / 固相 / 剂量</text><path d=\"M194 59h12m-5-5 5 5-5 5\" fill=\"none\" stroke=\"var(--jade,#2f7d6b)\" stroke-width=\"2\"/><rect x=\"208\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"295\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">PV 与 YP</text><text x=\"295\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">黏度斜率 / 屈服截距</text><path d=\"M384 59h12m-5-5 5 5-5 5\" fill=\"none\" stroke=\"var(--jade,#2f7d6b)\" stroke-width=\"2\"/><rect x=\"398\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"485\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">目标性能窗口</text><text x=\"485\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">相对成本最小配方</text></svg></div><figcaption class=\"figcap\">业务关系示意，不是测量结果。窄屏可在图内横向滚动。</figcaption></figure>"},{"no":2,"en":"METHOD","title":"双输出回归与配方搜索","html":"<p>使用温度、固相、两类处理剂和处理剂交互项，分别训练预测 PV、YP 的岭回归；验证批次选择正则强度。固定循环状态时搜索 961 个剂量组合，先判断两项性能是否均在目标窗口，再按人为设定的相对加剂成本排序。无解时保留无解结果，避免给出不满足目标的配方。</p>"},{"no":3,"en":"DATA","title":"数据准备与评价切分","html":"<p>种子 20261026，18 批、每批 10 条，共 180 条教学小试。前 12 批训练，3 批验证，3 批测试，各批互斥。温度 30–110 °C、固相 2–8%、两剂 0–3 归一化单位均为教学范围。现场应关联配方、批次、测量温度、流变仪读数和处理剂加量时序；本例只处理静态小试记录，没有模拟循环时延。</p>"},{"no":4,"en":"LIMITS","title":"模型适用范围与工程约束","html":"<p>没有预测密度、滤失、ECD 或化学相容性，不能称全性能闭环调控。归一化剂量和成本不对应现场浓度或金额；点击应用是替换假想配方，不是向已有体系连续加药。训练与测试共用人工响应机制，高评分不能证明真实配方优化收益。</p><p>专业资料与方法来源：</p><ul><li><a href=\"https://glossary.slb.com/en/terms/b/bingham_plastic_model\" target=\"_blank\" rel=\"noopener noreferrer\">SLB：Bingham plastic model</a>：支持两参数流变模型及 PV/YP 含义，不支持本例加剂响应系数和窗口。</li><li><a href=\"https://glossary.slb.com/en/terms/r/rheological_property\" target=\"_blank\" rel=\"noopener noreferrer\">SLB：rheological property</a>：支持多种流变模型及测量背景，不应将 Bingham 模型用于所有钻井液。</li></ul>"}]},"workflow":{"label":"案例流程","title":"双输出回归与配方搜索","lead":["钻井液流变性能影响流动阻力和岩屑输送，处理剂作用又随温度和固相状态改变。小试记录可用于建立轻量代理模型，比较性能窗口内的加剂方案，减少只凭单一性能调节的盲目性。"],"stats":[["数据","固定种子合成"],["运行方式","浏览器本地"],["工程用途","方法教学"]],"steps":[{"name":"小试批次切分","role":"数据","do":"18 批按 12/3/3 训练、验证和测试分组。","effect":"保留独立批次评价。","trap":"实测小试必须记录温度、仪器和批次条件。"},{"name":"流变代理模型","role":"算法","do":"两项岭回归预测 PV、YP，验证集从四个 λ 选择模型。","effect":"快速比较候选组合响应。","trap":"测试标签不能参与选型或系数拟合。"},{"name":"约束配方网格搜索","role":"优化","do":"在 961 个组合中筛选目标窗口内最低相对成本。","effect":"同时考虑两项性能和加剂代价。","trap":"目标冲突或模型覆盖不足时可能无解。"},{"name":"独立批次评价","role":"评价","do":"计算 PV、YP 的测试 MAE，并与训练均值基线比较。","effect":"使预测误差和推荐依据可核查。","trap":"预测可行性仍需真实小试验证。"}],"metrics":{"title":"计算指标与评价边界","html":"<figure class=\"figure\"><div style=\"overflow-x:auto\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 118\" role=\"img\" aria-label=\"案例计算流程\" style=\"width:100%;min-width:560px;max-width:640px;display:block;margin:auto\"><rect x=\"18\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"105\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">分批训练与验证</text><text x=\"105\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">PV / YP 双代理模型</text><path d=\"M194 59h12m-5-5 5 5-5 5\" fill=\"none\" stroke=\"var(--jade,#2f7d6b)\" stroke-width=\"2\"/><rect x=\"208\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"295\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">目标约束搜索</text><text x=\"295\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">961 配方 / 相对成本</text><path d=\"M384 59h12m-5-5 5 5-5 5\" fill=\"none\" stroke=\"var(--jade,#2f7d6b)\" stroke-width=\"2\"/><rect x=\"398\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"485\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">小试复核入口</text><text x=\"485\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">独立测试误差 / 无解</text></svg></div><figcaption class=\"figcap\">输入、计算与评价之间的关系示意；结果由演示实际计算。</figcaption></figure><p>PV 与 YP 的 MAE 分别以 mPa·s 和 Pa 报告，不混合物理单位。模型选择使用经人为尺度 1 mPa·s 与 1 Pa 归一化的两项验证 MAE 之和；测试集不参加选择。相对成本=2×增黏剂+稀释剂；推荐仅从符合 PV/YP 上下限的组合产生。Bingham 曲线中 PV 除以 1000 完成 mPa·s 到 Pa·s 换算。</p>"},"fails":[{"name":"数据分布变化","why":"没有预测密度、滤失、ECD 或化学相容性，不能称全性能闭环调控。归一化剂量和成本不对应现场浓度或金额；点击应用是替换假想配方，不是向已有体系连续加药。训练与测试共用人工响应机制，高评分不能证明真实配方优化收益。"},{"name":"合成结果误用","why":"所有数据、参数范围、阈值和响应系数均为教学合成设定；资料只支持业务定义和方法动机，不支持本例数值与现场收益。"}]},"demo":{"mode":"page","html":"demo/index.html","js":"demo/demo.js","label":"案例演示","height":1200,"intro":"钻井液流变性能影响流动阻力和岩屑输送，处理剂作用又随温度和固相状态改变。小试记录可用于建立轻量代理模型，比较性能窗口内的加剂方案，减少只凭单一性能调节的盲目性。"}}},"files":[{"name":"demo/demo.css","size":3674,"enc":"text","data":":root{font:16px/1.8 -apple-system,BlinkMacSystemFont,\"Segoe UI\",\"Microsoft YaHei\",sans-serif;color:#242b2e;background:#fbfaf6;--jade:#2f7d6b;--line:#ddd7c8;--muted:#56646b}\n*{box-sizing:border-box}body{margin:0}main{max-width:1200px;margin:auto;padding:24px}h1,h2,h3,p{margin:0}h1{font-size:clamp(24px,3vw,32px);line-height:1.4;margin:12px 0}h2{font-size:21px;line-height:1.5;margin-bottom:12px}h3{font-size:18px;margin:20px 0 10px}p{color:var(--muted)}header{margin-bottom:24px}header p{max-width:80ch}.badge{font-size:14px;color:#235f51;background:#e6f1ec;border-radius:4px;padding:5px 9px}.experiment{display:grid;grid-template-columns:285px minmax(0,1fr);border:1px solid var(--line);border-radius:12px;overflow:hidden;background:white}aside{background:#f3f5f0;padding:22px;border-right:1px solid var(--line)}.field{display:block;margin:18px 0}.field>span{display:flex;flex-wrap:wrap;justify-content:space-between;gap:6px;font-weight:600}.field output{color:var(--jade);font-variant-numeric:tabular-nums}input,select,button{font:inherit}input[type=range]{width:100%;accent-color:var(--jade);margin:14px 0;cursor:pointer}select{display:block;width:100%;min-height:44px;margin:8px 0;border:1px solid var(--line);border-radius:5px;background:white;padding:7px}small,.hint,.boundary{font-size:14px;color:var(--muted);line-height:1.75}.boundary{margin-top:18px;border-top:1px solid var(--line);padding-top:12px}button{min-height:44px;padding:8px 14px;color:white;background:var(--jade);border:1px solid var(--jade);border-radius:6px;cursor:pointer}button.quiet{background:white;color:var(--jade);border-color:var(--line)}button[hidden]{display:none}button:hover{filter:brightness(.95)}:focus-visible{outline:3px solid #41699b;outline-offset:3px}.results{padding:24px;min-width:0}.metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.metrics>div{padding:12px 14px;background:#f5f7f4;border:1px solid #e3e8e4;border-radius:6px}.metrics span{display:block;font-size:14px;color:var(--muted)}.metrics strong{display:block;font-size:23px;font-weight:600;line-height:1.5;color:#235f51;font-variant-numeric:tabular-nums}#status{padding:14px 0;font-size:15px}#apply{margin-bottom:16px}.chart{border-top:1px solid var(--line);padding-top:22px;margin-top:22px}.chart p{font-size:15px;line-height:1.8}.chart-scroll,.table-scroll{overflow:auto;overscroll-behavior-x:contain;padding-bottom:6px}svg{width:100%;max-width:700px;height:auto;display:block;margin:12px auto 4px}svg text{font:16px -apple-system,BlinkMacSystemFont,\"Microsoft YaHei\",sans-serif;fill:var(--muted)}.legend{display:flex;gap:10px 18px;flex-wrap:wrap;font-size:14px}.legend span{display:flex;align-items:center;gap:7px}.legend i{display:block;width:14px;height:4px}.details{margin-top:28px}.details>p{max-width:95ch}table{width:100%;border-collapse:collapse;font-size:15px;font-variant-numeric:tabular-nums}th,td{text-align:left;padding:9px 12px;border-bottom:1px solid var(--line);white-space:nowrap}th{background:#f3f5f0;font-weight:600}#download{margin-top:18px}footer{font-size:14px;color:var(--muted);padding:18px 0;margin-top:26px;border-top:1px solid var(--line)}\n@media(max-width:1000px){.experiment{grid-template-columns:1fr}aside{border-right:0;border-bottom:1px solid var(--line)}#controls{display:grid;grid-template-columns:1fr 1fr;gap:0 24px}.field{margin:10px 0}}\n@media(max-width:600px){main{padding:12px}.results,aside{padding:16px}#controls{grid-template-columns:1fr}.metrics{gap:8px}.metrics strong{font-size:20px}.chart-scroll svg{width:640px;max-width:none}.badge{display:inline-block;font-size:13px}}\n@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}\n"},{"name":"demo/demo.js","size":4888,"enc":"text","data":"(function(){\n  'use strict';const M=FluidModel,F=CaseUI.f,data=M.generate(),learned=M.train(data),model=learned.model;\n  CaseUI.mount({id:'drilling-fluid',title:'钻井液性能智能调控',intro:'以温度、固相含量和处理剂剂量预测塑性黏度 PV 与动切力 YP，在目标性能窗口内寻找最低相对加剂成本。约束收紧时可能没有可行配方。',boundary:'剂量是每份教学配方的归一化单位。不能换算为现场 kg/m³；只调控流变性能，不涉及密度、滤失、ECD、化学相容性或井壁稳定。',controls:[{id:'temp',label:'循环温度',min:30,max:110,step:5,value:70,unit:'°C'},{id:'solids',label:'固相体积分数',min:2,max:8,step:.5,value:5,unit:'%'},{id:'polymer',label:'当前增黏剂',min:0,max:3,step:.1,value:1,unit:'单位'},{id:'thinner',label:'当前稀释剂',min:0,max:3,step:.1,value:.2,unit:'单位'},{id:'pvMin',label:'PV 下限',min:10,max:28,step:1,value:17,unit:'mPa·s'},{id:'pvMax',label:'PV 上限',min:10,max:28,step:1,value:22,unit:'mPa·s'},{id:'ypMin',label:'YP 下限',min:3,max:23,step:1,value:13,unit:'Pa'},{id:'ypMax',label:'YP 上限',min:3,max:23,step:1,value:16,unit:'Pa'}],method:'种子 20261026，18 批共 180 条合成小试；按批分训练 12 批、验证 3 批、测试 3 批。两个岭回归分别预测 PV 和 YP，含温度、固相、两类处理剂及其交互项。验证集选择 λ，测试集只评价。搜索两剂各 0–3 单位、步长 0.1 的 961 个组合，满足四个性能边界后取 2×增黏剂+稀释剂 最小值。采用 Bingham 关系 τ=YP+PV×γ/1000 显示流变曲线，PV 用 mPa·s、剪切速率用 s⁻¹，换算后 τ 为 Pa。',\n    compute:s=>{const search=M.optimize(model,s),best=search.best,current=model.predict(s),valid=s.pvMin<=s.pvMax&&s.ypMin<=s.ypMax;\n      const flow=p=>Array.from({length:21},(_,i)=>[i*50,p.yp+p.pv*i*50/1000]);\n      return {metrics:[['当前预测 PV',F(current.pv)+' mPa·s'],['当前预测 YP',F(current.yp)+' Pa'],['可行配方数',String(search.grid.filter(r=>r.valid).length)],['推荐相对成本',best?F(best.cost)+' 单位':'无可行配方'],['测试 PV MAE',F(learned.score.pv)+' mPa·s'],['测试 YP MAE',F(learned.score.yp)+' Pa']],summary:!valid?'目标下限大于上限，无法推荐。':best?`推荐增黏剂 ${F(best.polymer,1)}、稀释剂 ${F(best.thinner,1)} 单位；预测 PV ${F(best.pv)}、YP ${F(best.yp)}，λ=${model.lambda}。应用按钮只替换教学配方参数，不累加药剂。`:'当前网格中无满足目标窗口的组合，请调整目标或检查模型适用范围。',apply:best?{polymer:best.polymer,thinner:best.thinner}:null,\n        plots:[{title:'配方性能与可行窗口',xLabel:'预测 PV mPa·s',yLabel:'预测 YP Pa',xDecimals:1,hlines:[s.ypMin,s.ypMax],vlines:[s.pvMin,s.pvMax],note:'绿色点为满足全部目标的配方，灰点越界；虚线围成目标窗口，蓝点为最低相对成本推荐。每个点由训练模型计算。',series:[{name:'越界配方',dots:true,color:'#a5ada8',points:search.grid.filter(r=>!r.valid).map(r=>[r.pv,r.yp])},{name:'可行配方',dots:true,color:'#2f7d6b',points:search.grid.filter(r=>r.valid).map(r=>[r.pv,r.yp])},{name:'推荐配方',dots:true,color:'#41699b',points:best?[[best.pv,best.yp]]:[]},{name:'当前配方',dots:true,color:'#b26a39',points:[[current.pv,current.yp]]}]},\n        {title:'当前与推荐流变曲线',xLabel:'剪切速率 s⁻¹',yLabel:'剪切应力 Pa',note:'Bingham 近似用于解释 PV 是斜率、YP 是截距；不能覆盖所有钻井液的非牛顿流动。',series:[{name:'当前配方',points:flow(current)},...(best?[{name:'推荐配方',points:flow(best)}]:[])]},\n        ...['pv','yp'].map(k=>({title:k==='pv'?'独立测试批次 PV 误差':'独立测试批次 YP 误差',xLabel:'合成观测 '+(k==='pv'?'PV mPa·s':'YP Pa'),yLabel:'模型预测 '+(k==='pv'?'PV mPa·s':'YP Pa'),xRange:[0,30],yRange:[0,30],note:'测试批次不参与训练或模型选择；对角线为理想预测，偏离表示误差。',series:[{name:'独立测试样本',dots:true,points:learned.test.map(r=>[r[k],model.predict(r)[k]])},{name:'理想一致线',dashed:true,points:[[0,0],[30,30]]}]}))],\n        table:{title:'训练与独立测试评价',headers:['对象','样本数','PV MAE mPa·s','YP MAE Pa'],rows:[...learned.candidates.map(c=>['验证 λ='+c.model.lambda,30,F(c.score.pv,3),F(c.score.yp,3)]),['冻结模型测试',30,F(learned.score.pv,3),F(learned.score.yp,3)],['训练均值基线测试',30,F(learned.baseline.pv,3),F(learned.baseline.yp,3)]],note:'验证指标只用于选择 λ；测试批次与训练批次不重叠。合成数据来自同一人工机制，评分不代表现场泛化。CSV 包含切分、输入、观测与冻结模型预测。'},records:data.map(r=>({...r,predicted_pv:model.predict(r).pv,predicted_yp:model.predict(r).yp}))};}\n  });\n})();\n"},{"name":"demo/index.html","size":425,"enc":"text","data":"<!doctype html>\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>钻井液性能智能调控</title><link rel=\"stylesheet\" href=\"demo.css\"></head><body><main id=\"app\"></main><noscript>需要启用 JavaScript 才能运行本地计算。</noscript><script src=\"model.js\"></script><script src=\"ui.js\"></script><script src=\"demo.js\"></script></body></html>"},{"name":"demo/model.js","size":2980,"enc":"text","data":"(function(g){\n  'use strict';\n  function features(s){return [1,(s.temp-60)/40,(s.solids-5)/3,s.polymer,s.thinner,s.polymer*s.thinner];}\n  function truth(s){const t=(s.temp-60)/40,c=(s.solids-5)/3;return {pv:18+3*c-2*t+2.1*s.polymer-1.8*s.thinner+.2*s.polymer*s.thinner,yp:11+1.8*c-t+3.2*s.polymer-2.8*s.thinner-.35*s.polymer*s.thinner};}\n  function generate(){let seed=20261026;const rand=()=>{seed=(1664525*seed+1013904223)>>>0;return seed/4294967296;};\n    return Array.from({length:180},(_,i)=>{const s={batch:Math.floor(i/10)+1,split:i<120?'train':i<150?'validation':'test',temp:30+rand()*80,solids:2+rand()*6,polymer:rand()*3,thinner:rand()*3};const y=truth(s);return {...s,pv:y.pv+(rand()-.5)*1.4,yp:y.yp+(rand()-.5)*1.2};});\n  }\n  function solve(a,b){const m=a.map((r,i)=>r.concat(b[i]));for(let i=0;i<b.length;i++){let p=i;for(let k=i+1;k<b.length;k++)if(Math.abs(m[k][i])>Math.abs(m[p][i]))p=k;[m[p],m[i]]=[m[i],m[p]];if(Math.abs(m[i][i])<1e-12)throw Error('singular');const v=m[i][i];for(let j=i;j<=b.length;j++)m[i][j]/=v;for(let k=0;k<b.length;k++)if(k!==i){const f=m[k][i];for(let j=i;j<=b.length;j++)m[k][j]-=f*m[i][j];}}return m.map(r=>r[b.length]);}\n  function fit(rows,lambda){const a=Array.from({length:6},()=>Array(6).fill(0)),b={pv:Array(6).fill(0),yp:Array(6).fill(0)};rows.forEach(r=>{const x=features(r);x.forEach((v,j)=>{x.forEach((u,k)=>a[j][k]+=v*u);for(const key of ['pv','yp'])b[key][j]+=v*r[key];});});for(let j=1;j<6;j++)a[j][j]+=lambda;const beta={pv:solve(a,b.pv),yp:solve(a,b.yp)};return {lambda,beta,predict:s=>{const x=features(s),out={};for(const k of ['pv','yp'])out[k]=x.reduce((sum,v,j)=>sum+v*beta[k][j],0);return out;}};}\n  function evaluate(model,rows){return Object.fromEntries(['pv','yp'].map(k=>[k,rows.reduce((s,r)=>s+Math.abs(model.predict(r)[k]-r[k]),0)/rows.length]));}\n  function train(rows){const training=rows.filter(r=>r.split==='train'),validation=rows.filter(r=>r.split==='validation'),test=rows.filter(r=>r.split==='test');const candidates=[.01,.1,1,10].map(l=>{const model=fit(training,l);return {model,score:evaluate(model,validation)};});const chosen=candidates.reduce((a,b)=>a.score.pv+a.score.yp<=b.score.pv+b.score.yp?a:b);const avg=Object.fromEntries(['pv','yp'].map(k=>[k,training.reduce((s,r)=>s+r[k],0)/training.length]));return {model:chosen.model,candidates,test,score:evaluate(chosen.model,test),baseline:evaluate({predict:()=>avg},test)};}\n  function optimize(model,s){const grid=[];let best=null;for(let i=0;i<=30;i++)for(let j=0;j<=30;j++){const polymer=i/10,thinner=j/10,p=model.predict({...s,polymer,thinner}),cost=2*polymer+thinner,valid=p.pv>=s.pvMin&&p.pv<=s.pvMax&&p.yp>=s.ypMin&&p.yp<=s.ypMax;const r={polymer,thinner,...p,cost,valid};grid.push(r);if(valid&&(!best||cost<best.cost))best=r;}return {best,grid};}\n  const api={features,truth,generate,fit,train,evaluate,optimize};if(typeof module!=='undefined')module.exports=api;else g.FluidModel=api;\n})(typeof window!=='undefined'?window:globalThis);\n"},{"name":"demo/ui.js","size":6241,"enc":"text","data":"(function(g){\n  'use strict';\n  const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n  const f=(v,n=2)=>v===null||!Number.isFinite(v)?'不可定义':v.toFixed(n);\n  function plot(p,index){\n    const W=700,H=340,L=85,R=24,T=38,B=64;\n    const all=p.series.flatMap(s=>s.points).filter(a=>a.every(Number.isFinite));\n    const extent=(k)=>{const v=all.map(a=>a[k]);let a=Math.min(...v),b=Math.max(...v);if(a===b){a-=1;b+=1;}return [a,b];};\n    const xr=p.xRange||extent(0),yr=p.yRange||extent(1),x=v=>L+(v-xr[0])/(xr[1]-xr[0])*(W-L-R),y=v=>H-B-(v-yr[0])/(yr[1]-yr[0])*(H-T-B);\n    let svg=`<defs><clipPath id=\"clip${index}\"><rect x=\"${L}\" y=\"${T}\" width=\"${W-L-R}\" height=\"${H-T-B}\"/></clipPath></defs>`;\n    for(let i=0;i<=4;i++){const xv=xr[0]+(xr[1]-xr[0])*i/4,yv=yr[0]+(yr[1]-yr[0])*i/4;svg+=`<path d=\"M${L} ${y(yv)}H${W-R}\" stroke=\"#e3e8e4\"/><text x=\"${L-10}\" y=\"${y(yv)+5}\" text-anchor=\"end\">${f(yv,p.decimals??1)}</text><text x=\"${x(xv)}\" y=\"${H-B+27}\" text-anchor=\"middle\">${f(xv,p.xDecimals??0)}</text>`;}\n    svg+=`<text x=\"${L}\" y=\"22\">${esc(p.yLabel)}</text><text x=\"${(L+W-R)/2}\" y=\"${H-8}\" text-anchor=\"middle\">${esc(p.xLabel)}</text><g clip-path=\"url(#clip${index})\">`;\n    (p.bands||[]).forEach(b=>{svg+=`<rect x=\"${x(b.from)}\" y=\"${T}\" width=\"${x(b.to)-x(b.from)}\" height=\"${H-T-B}\" fill=\"#f8ecdf\"/>`;});\n    (p.hlines||[]).forEach(v=>svg+=`<path d=\"M${L} ${y(v)}H${W-R}\" stroke=\"#a34138\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/>`);\n    (p.vlines||[]).forEach(v=>svg+=`<path d=\"M${x(v)} ${T}V${H-B}\" stroke=\"#8e5229\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/>`);\n    const colors=['#2f7d6b','#41699b','#b26a39','#7e5a8d'];\n    p.series.forEach((s,i)=>{const pts=s.points.filter(a=>a.every(Number.isFinite)),color=s.color||colors[i%4];if(s.dots)pts.forEach(a=>svg+=`<circle cx=\"${x(a[0])}\" cy=\"${y(a[1])}\" r=\"3.5\" fill=\"${color}\" opacity=\".65\"><title>${esc(s.name)}：${f(a[0])}, ${f(a[1])}</title></circle>`);else svg+=`<path d=\"${pts.map((a,j)=>(j?'L':'M')+x(a[0])+','+y(a[1])).join(' ')}\" fill=\"none\" stroke=\"${color}\" stroke-width=\"2.5\" ${s.dashed?'stroke-dasharray=\"7 5\"':''}/>`;});svg+='</g>';\n    return `<article class=\"chart\"><h2>${esc(p.title)}</h2><p>${esc(p.note)}</p><div class=\"chart-scroll\" role=\"region\" tabindex=\"0\" aria-label=\"${esc(p.title)}，窄屏可横向滚动\"><svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"${esc(p.title+'；'+p.yLabel+'；'+p.xLabel)}\">${svg}</svg></div><div class=\"legend\">${p.series.map((s,i)=>`<span><i style=\"background:${s.color||colors[i%4]}\"></i>${esc(s.name)}</span>`).join('')}</div></article>`;\n  }\n  function mount(c){\n    const root=document.getElementById('app');let result;\n    root.innerHTML=`<header><span class=\"badge\">教学合成数据 · 本地计算 · 固定种子</span><h1>${esc(c.title)}</h1><p>${esc(c.intro)}</p></header><section class=\"experiment\"><aside><h2>实验设置</h2><form id=\"controls\">${c.controls.map(a=>`<label class=\"field\" for=\"${a.id}\"><span>${esc(a.label)} <output id=\"${a.id}-value\"></output></span>${a.options?`<select id=\"${a.id}\">${a.options.map(o=>`<option value=\"${esc(o[0])}\">${esc(o[1])}</option>`).join('')}</select>`:`<input id=\"${a.id}\" type=\"range\" min=\"${a.min}\" max=\"${a.max}\" step=\"${a.step}\" value=\"${a.value}\">`}<small>${esc(a.hint||'')}</small></label>`).join('')}</form><button id=\"reset\" class=\"quiet\" type=\"button\">恢复初始设置</button><p class=\"boundary\">${esc(c.boundary)}</p></aside><div class=\"results\"><h2>计算结果</h2><div id=\"metrics\" class=\"metrics\"></div><p id=\"status\" role=\"status\"></p><button id=\"apply\" type=\"button\" hidden>应用推荐参数</button><div id=\"plots\"></div></div></section><section class=\"details\"><h2>方法与评价边界</h2><p>${esc(c.method)}</p><div id=\"table\"></div><button id=\"download\" class=\"quiet\" type=\"button\">导出当前实验 CSV</button></section><footer>所有范围、阈值、响应系数和目标均为教学设置；合成评价不能证明现场效果。演示不连接设备。图表可通过下方数据表及 CSV 核对。</footer>`;\n    const read=()=>Object.fromEntries(c.controls.map(a=>[a.id,a.options?document.getElementById(a.id).value:+document.getElementById(a.id).value]));\n    function render(){const s=read();c.controls.forEach(a=>document.getElementById(a.id+'-value').textContent=a.options?'':s[a.id]+(a.unit?' '+a.unit:''));result=c.compute(s);document.getElementById('metrics').innerHTML=result.metrics.map(a=>`<div><span>${esc(a[0])}</span><strong>${esc(a[1])}</strong></div>`).join('');document.getElementById('status').textContent=result.summary;document.getElementById('plots').innerHTML=result.plots.map(plot).join('');const table=result.table;document.getElementById('table').innerHTML=`<h3>${esc(table.title)}</h3><div class=\"table-scroll\"><table><thead><tr>${table.headers.map(v=>`<th scope=\"col\">${esc(v)}</th>`).join('')}</tr></thead><tbody>${table.rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class=\"hint\">${esc(table.note||'')}</p>`;document.getElementById('apply').hidden=!result.apply;}\n    document.getElementById('controls').addEventListener('submit',e=>e.preventDefault());\n    c.controls.forEach(a=>document.getElementById(a.id).addEventListener(a.options?'change':'input',render));\n    document.getElementById('reset').onclick=()=>{c.controls.forEach(a=>document.getElementById(a.id).value=a.value);render();};\n    document.getElementById('apply').onclick=()=>{if(result.apply){Object.entries(result.apply).forEach(([k,v])=>document.getElementById(k).value=v);render();}};\n    document.getElementById('download').onclick=()=>{const rows=result.records;if(!rows.length)return;const keys=Object.keys(rows[0]),cell=v=>'\"'+String(v??'').replace(/\"/g,'\"\"')+'\"';const csv='\\uFEFF'+[keys,...rows.map(r=>keys.map(k=>r[k]))].map(r=>r.map(cell).join(',')).join('\\r\\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=c.id+'-synthetic.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};\n    c.controls.forEach(a=>document.getElementById(a.id).value=a.value);render();\n  }\n  g.CaseUI={mount,f,plot};\n})(window);\n"}]};
  // Local uploads take precedence. Keep the original importer and its package contract.
  var sc = global.ATLAS.index.byScene[pack.manifest.sceneId];
  var existing = global.Cases.get(pack.manifest.id);
  if (existing) {
    if (sc && existing.tabs && existing.tabs.demo) sc.demo = true;
    return;
  }
  if (global.CaseImport.blockedList().indexOf(pack.manifest.id) >= 0) return;
  var c = pack.manifest;
  var cfg = c.tabs.demo;
  var handle = null;
  c.status = 'ready';
  c.tabs.demo = {
    label: cfg.label, intro: cfg.intro,
    mount: function (root, ctx) {
      handle = global.CaseDemoHost.create(root, { files: pack.files, demo: cfg, meta: c }, ctx);
    },
    unmount: function () { if (handle) { handle.destroy(); handle = null; } }
  };
  global.Cases.register(c);
  if (sc) sc.demo = true;
})(window);
